<template>
  <div class="evaluation-module-page page-container">
    <header class="module-header"><div><div class="header-title"><el-icon><RefreshRight /></el-icon><h1>模型迭代优化与 Retraining 中心</h1><el-tag type="success" effect="plain">AI 迭代闭环</el-tag></div><p>执行自动调优、人工微调与自动化重训，验证新旧版本效果并回流预测引擎</p></div><div class="header-actions"><el-button :icon="Setting" @click="router.push('/prediction-evaluation/config#retraining')">自动化策略</el-button><el-button :icon="Document" @click="logVisible=true">迭代日志</el-button></div></header>
    <div class="page-workspace"><TaskList/><main class="business-content">
      <section class="context-bar surface"><div><small>当前优化对象</small><strong>{{currentTask?.name}} · {{currentTask?.version}}</strong></div><div class="header-actions"><el-button :icon="Operation" @click="manualVisible=true">手动精准调优</el-button><el-button :icon="MagicStick" :loading="tuning" @click="autoTune">自动调优</el-button><el-button type="primary" :icon="RefreshRight" :loading="retraining" @click="retrain">触发 Retraining</el-button></div></section>
      <section class="status-strip"><div><small>当前迭代状态</small><h3>{{state.title}}</h3><p>{{state.desc}}</p></div><div><div class="progress-title"><span>流程进度</span><b>{{state.progress}}%</b></div><el-progress :percentage="state.progress" :show-text="false" :stroke-width="9"/></div><div class="status-meta"><span><small>触发方式</small><b>{{state.trigger}}</b></span><span><small>预计完成</small><b>{{state.eta}}</b></span></div></section>
      <div class="equal-column"><section class="surface"><div class="section-head"><div><h2>重训前后效果对比</h2><p v-if="comparisonMeta">{{comparisonMeta}}</p><p v-else>由后端模型版本对比接口提供，未完成评估时不展示虚构数据</p></div></div><div v-if="!comparisonRows.length" class="empty-action"><el-empty description="暂无重训前后评估记录" :image-size="70"/><el-button type="primary" plain :disabled="!selectedId" :loading="retraining" :icon="RefreshRight" @click="retrain">触发 Retraining 生成对比</el-button></div><div v-else class="comparison"><div v-for="m in comparisonRows" :key="m.name"><span>{{m.name}}</span><div><i :style="{width:m.beforeBar+'%'}"></i><i :style="{width:m.afterBar+'%'}"></i></div><b>{{m.beforeLabel}} → {{m.afterLabel}}</b></div><footer><span><i></i>重训前</span><span><i></i>重训后</span></footer></div></section><section class="surface"><div class="section-head"><div><h2>自动调优结果</h2><p>参数建议由后端自动调优接口返回</p></div></div><div v-if="!suggestions.length" class="empty-action"><el-empty description="请先执行自动调优" :image-size="70"/><el-button type="primary" plain :disabled="!selectedId" :loading="tuning" :icon="MagicStick" @click="autoTune">执行自动调优</el-button></div><div v-else class="list-rows"><div v-for="s in suggestions" :key="s.name"><span class="number-icon"><el-icon><Check/></el-icon></span><div><b>{{s.name}}</b><small>{{s.desc}}</small></div><strong class="param-value">{{s.value}}</strong></div></div></section></div>
      <section class="surface"><div class="section-head"><div><h2>Retraining 自动化流程</h2><p>数据准备、模型训练、效果验证与版本生成</p></div></div><el-steps :active="step" finish-status="success" align-center><el-step title="数据准备" description="异常样本与训练集"/><el-step title="参数调优" description="搜索最优组合"/><el-step title="模型训练" description="执行 Retraining"/><el-step title="效果验证" description="新旧版本对比"/><el-step title="版本生成" description="等待发布上线"/></el-steps></section>
      <section class="surface table-surface"><div class="section-head"><div><h2>模型版本迭代记录</h2><p>通过验证的新版本可直接回流模块 3 市场需求预测引擎</p></div><el-button :icon="Refresh" :loading="loading" @click="loadVersions">刷新状态</el-button></div><el-table :data="versions" height="285" empty-text="暂无模型版本"><el-table-column prop="version" label="版本" width="100"/><el-table-column prop="source" label="迭代方式"/><el-table-column prop="accuracy" label="准确率"/><el-table-column prop="mape" label="MAPE"/><el-table-column prop="createdAt" label="完成时间" min-width="150"/><el-table-column label="状态"><template #default="{row}"><el-tag size="small" :type="row.status==='生产中'?'success':row.status==='待发布'?'warning':'info'">{{row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button v-if="!row.isProduction" link type="primary" @click="publish(row)">推送上线</el-button><el-button v-if="row.isProduction" link type="danger" @click="rollback(row)">版本回滚</el-button><el-button link @click="viewVersion(row)">详情</el-button></template></el-table-column></el-table></section>
    </main></div>
    <el-dialog v-model="manualVisible" title="手动精准调优" width="560px"><el-form :model="manual" label-position="top"><div class="manual-grid"><el-form-item label="学习率"><el-input-number v-model="manual.learningRate" :step=".001"/></el-form-item><el-form-item label="迭代轮数"><el-input-number v-model="manual.epochs"/></el-form-item><el-form-item label="Batch Size"><el-select v-model="manual.batch"><el-option v-for="v in [16,32,64,128]" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="特征权重策略"><el-select v-model="manual.strategy"><el-option label="偏差贡献度优先" value="bias"/><el-option label="业务重要性优先" value="business"/></el-select></el-form-item></div><el-form-item label="调优说明"><el-input v-model="manual.note" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="manualVisible=false">取消</el-button><el-button type="primary" @click="submitManual">创建调优任务</el-button></template></el-dialog>
    <el-drawer v-model="logVisible" title="模型迭代操作日志" size="480px"><el-timeline><el-timeline-item v-for="v in versions" :key="v.version" :timestamp="v.createdAt"><b>{{v.version}} · {{v.source}}</b><p>准确率 {{v.accuracy}}，MAPE {{v.mape}}</p></el-timeline-item></el-timeline></el-drawer>
  </div>
</template>
<script setup>
import { onBeforeUnmount } from 'vue'
import { computed,defineComponent,h,onMounted,reactive,ref,watch } from 'vue';import { useRouter } from 'vue-router';import { ElButton,ElEmpty,ElInput,ElMessage,ElMessageBox,ElTag } from 'element-plus';import { Check,Document,MagicStick,Operation,Refresh,RefreshRight,Search,Setting } from '@element-plus/icons-vue';import { useEvaluationTasks } from '../composables/useEvaluationTasks';import request from '../utils/request';import '../assets/styles/evaluation-pages.css'
const router=useRouter();const {loading,selectedId,keyword,visibleTasks,currentTask,loadTasks}=useEvaluationTasks();const tuning=ref(false),retraining=ref(false),manualVisible=ref(false),logVisible=ref(false),step=ref(0);const state=reactive({title:'请选择预测任务',desc:'训练状态由后端任务和模型记录提供',progress:0,trigger:'—',eta:'—'});const comparisons=ref([]);const suggestions=ref([]);const versions=ref([]);const manual=reactive({learningRate:.018,epochs:460,batch:64,strategy:'bias',note:''});const comparisonRows=computed(()=>comparisons.value);const loadVersions=async()=>{try{const rows=await request.get('/v1/predictions/models');versions.value=(rows||[]).filter(row=>!selectedId.value||row.predictionTaskId===selectedId.value).map(row=>({ ...row, version:`v${row.versionNumber||1}`, source:'模型版本', accuracy:row.mape==null?'—':`${(100-Number(row.mape)).toFixed(1)}%`, mape:row.mape==null?'—':`${row.mape}%`, createdAt:row.createdAt, status:row.isProduction?'生产中':row.status||'ACTIVE'}))}catch(e){versions.value=[];ElMessage.error(`模型版本加载失败：${e.message||'后端接口不可用'}`)}};async function autoTune(){if(!selectedId.value)return ElMessage.warning('请选择预测任务');tuning.value=true;try{const result=await request.post(`/v1/predictions/${selectedId.value}/auto-tune`);suggestions.value=Object.entries(result.parameters||result.bestParameters||result.candidates?.[0]||{}).map(([name,value])=>({name,desc:'后端自动调优返回参数',value:String(value)}));state.title='自动调优已完成';state.desc=result.message||'候选模型已完成比较';state.progress=100;state.trigger='人工触发';state.eta='已完成';await loadVersions();ElMessage.success('自动调优任务已完成')}catch(e){ElMessage.error(`自动调优失败：${e?.response?.data?.message||e.message||'后端接口不可用'}`)}finally{tuning.value=false}}async function retrain(){if(!selectedId.value)return ElMessage.warning('请选择预测任务');try{await ElMessageBox.confirm('确认基于当前模型和偏差结果启动 Retraining？','触发重训练',{type:'warning'})}catch(e){return}retraining.value=true;try{await request.post(`/v1/predictions/${selectedId.value}/retrain`);step.value=2;Object.assign(state,{title:'Retraining 已提交',desc:'后端已接收重训练任务，请通过任务状态查看进度',progress:0,trigger:'人工触发',eta:'以后端状态为准'});await loadVersions();ElMessage.success('Retraining 任务已提交')}catch(e){ElMessage.error(`Retraining 失败：${e?.response?.data?.message||e?.response?.data?.error||e?.message||'后端接口不可用'}`)}finally{retraining.value=false}}async function submitManual(){if(!selectedId.value)return ElMessage.warning('请选择预测任务');tuning.value=true;try{const result=await request.post(`/v1/predictions/${selectedId.value}/manual-tune`,{learningRate:manual.learningRate,epochs:manual.epochs,batchSize:manual.batch,featureWeightStrategy:manual.strategy,note:manual.note});suggestions.value=Object.entries(result.parameters||{}).map(([name,value])=>({name,desc:'后端人工调优已应用参数',value:String(value)}));manualVisible.value=false;state.title='手动调优已完成';state.desc='参数已应用并生成新的模型版本';state.progress=100;state.trigger='人工调优';state.eta='已完成';step.value=1;await loadVersions();ElMessage.success('手动精准调优已完成')}catch(e){ElMessage.error(`手动调优失败：${e?.response?.data?.message||e.message||'后端接口不可用'}`)}finally{tuning.value=false}}async function publish(row){try{await request.post(`/v1/predictions/models/${row.id}/set-production`);await loadVersions();ElMessage.success(`${row.version} 已推送至预测引擎`)}catch(e){ElMessage.error(`发布失败：${e?.response?.data?.message||e.message||'后端接口不可用'}`)}}async function rollback(row){if(!selectedId.value)return;try{await ElMessageBox.confirm(`确认回滚 ${row.version}？`,'版本回滚',{type:'warning'});await request.post(`/v1/predictions/${selectedId.value}/rollback`,{modelVersionId:row.id});await loadVersions();ElMessage.success('版本回滚已提交')}catch(e){if(e!=='cancel')ElMessage.error(`回滚失败：${e?.response?.data?.message||e.message||'后端接口不可用'}`)}}function viewVersion(row){ElMessage.info(`${row.version}：${row.source}，准确率 ${row.accuracy}`)}
watch(selectedId, loadVersions, { immediate:true });onMounted(loadVersions)

const comparisonMeta=ref('')
function syncWorkflowStep(status) {
  const normalized = String(status || '').toUpperCase()
  if (normalized === 'RETRAINING' || normalized === 'TRAINING') step.value = 2
  else if (normalized === 'COMPLETED' && comparisonRows.value.length) step.value = 4
  else if (normalized === 'COMPLETED') step.value = 3
}
async function loadComparison(){
  comparisons.value=[]
  comparisonMeta.value=''
  if(!selectedId.value) return
  try {
    const rows=await request.get('/v1/predictions/models')
    const taskRows=(rows||[]).filter(row=>row.predictionTaskId===selectedId.value).sort((a,b)=>(a.versionNumber||0)-(b.versionNumber||0))
    if(taskRows.length<2) return
    const before=taskRows[taskRows.length-2], after=taskRows[taskRows.length-1]
    const result=await request.post('/v1/predictions/models/compare',{modelId1:before.id,modelId2:after.id})
    const left=result.model1||{}, right=result.model2||{}
    const definitions=[['准确率',m=>m.mape==null?null:Math.max(0,100-Number(m.mape)),'%'],['MAE',m=>m.mae,''],['RMSE',m=>m.rmse,''],['MAPE',m=>m.mape,'%']]
    comparisons.value=definitions.map(([name,get,suffix])=>{const l=get(left)==null?null:Number(get(left)),r=get(right)==null?null:Number(get(right)),max=Math.max(l||0,r||0,1);return {name,beforeBar:Math.min(100,(l||0)/max*100),afterBar:Math.min(100,(r||0)/max*100),beforeLabel:l==null?'—':`${l.toFixed(2)}${suffix}`,afterLabel:r==null?'—':`${r.toFixed(2)}${suffix}`}}).filter(row=>row.beforeLabel!=='—'||row.afterLabel!=='—')
    comparisonMeta.value=`v${before.versionNumber||1} → v${after.versionNumber||1} · 后端评估结果`
    if (comparisonRows.value.length) syncWorkflowStep('COMPLETED')
  } catch (_) { comparisonMeta.value='模型版本对比暂不可用，请完成评估后重试' }
}
watch(selectedId,()=>{comparisons.value=[];loadComparison()},{immediate:true})
onMounted(loadComparison)

// Retraining runs asynchronously; keep the progress panel synchronized with the persisted task state.
const retrainStatusTimer = setInterval(async () => {
  if (!selectedId.value) return
  try {
    const task = await request.get(`/v1/predictions/${selectedId.value}`)
    const status = String(task?.status || '').toUpperCase()
    if (status === 'RETRAINING') {
      syncWorkflowStep(status)
      Object.assign(state, { title: '正在 Retraining', desc: '后端正在执行模型重训练', progress: Math.max(state.progress, 55), trigger: '人工触发', eta: '以后端状态为准' })
    } else if (status === 'COMPLETED') {
      Object.assign(state, { title: 'Retraining 已完成', desc: '模型已完成训练并生成新版本', progress: 100, trigger: '人工触发', eta: '已完成' })
      await loadVersions()
      syncWorkflowStep(status)
    } else if (status === 'FAILED') {
      Object.assign(state, { title: 'Retraining 失败', desc: task.errorMessage || '后端未返回失败原因', progress: 100, trigger: '人工触发', eta: '已结束' })
    }
  } catch (_) {
    // The next poll retries without interrupting the page.
  }
}, 2000)
onBeforeUnmount(() => clearInterval(retrainStatusTimer))
const comparisonTimer=setInterval(loadComparison,3000)
onBeforeUnmount(() => clearInterval(comparisonTimer))
const TaskList=defineComponent({setup(){return()=>h('aside',{class:'task-sidebar'},[h('div',{class:'section-head'},[h('div',[h('h2','待优化模型'),h('p',`${visibleTasks.value.length} 个模型任务`)]),h(ElButton,{circle:true,icon:Refresh,loading:loading.value,onClick:loadTasks})]),h(ElInput,{modelValue:keyword.value,'onUpdate:modelValue':v=>keyword.value=v,prefixIcon:Search,placeholder:'搜索模型版本',clearable:true}),h('div',{class:'task-list'},visibleTasks.value.length?visibleTasks.value.map(t=>h('button',{class:['task-item',{active:selectedId.value===t.id}],onClick:()=>selectedId.value=t.id},[h('div',{class:'task-head'},[h('b',t.name),h(ElTag,{size:'small',type:t.status==='待优化'?'warning':'info'},()=>t.status)]),h('div',{class:'task-meta'},[h('span',t.model),h('span',t.version)]),h('div',{class:'task-stats'},[h('span',`准确率 ${t.accuracy??'--'}%`),h('span',`MAPE ${t.mape??'--'}%`)])])):h(ElEmpty,{imageSize:60,description:'暂无模型'})),h('div',{class:'task-source'},'优化版本通过验证后回流模块 3，操作日志同步模块 6')])}})
</script><style scoped>.progress-title{display:flex;justify-content:space-between;font-size:11px;margin-bottom:8px}.empty-action{display:flex;flex-direction:column;align-items:center;gap:4px;padding-bottom:10px}.empty-action :deep(.el-empty){padding:18px 0 4px}.comparison>div{display:grid;grid-template-columns:80px minmax(0,1fr) 92px;align-items:center;gap:10px;margin:17px 0;font-size:11px}.comparison>div>div{display:grid;gap:4px;min-width:0}.comparison i{display:block;height:7px;border-radius:4px;background:#c9cdd4}.comparison i+i{background:#165dff}.comparison footer{display:flex;justify-content:center;gap:22px;border-top:1px solid #f2f3f5;padding-top:12px;font-size:10px;color:#86909c}.comparison footer i{display:inline-block;width:8px;height:8px;margin-right:5px}.comparison footer span+span i{background:#165dff}.param-value{font-size:11px;color:#165dff;overflow-wrap:anywhere}.manual-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.manual-grid :deep(.el-input-number),.manual-grid :deep(.el-select){width:100%}.business-content{min-width:0;overflow:hidden}.context-bar>div:first-child{min-width:0;flex:1}.context-bar>div:first-child strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.context-bar .header-actions{flex-shrink:0;flex-wrap:wrap}.main-column,.panel,.surface{min-width:0}.workflow-panel :deep(.el-steps){min-width:0;overflow:hidden}.workflow-panel :deep(.el-step__title),.workflow-panel :deep(.el-step__description){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.table-surface :deep(.el-table){max-width:100%}@media(max-width:1100px){.page-workspace{grid-template-columns:220px minmax(0,1fr)!important;gap:12px!important}.context-bar{align-items:flex-start!important;flex-wrap:wrap}.context-bar .header-actions{width:100%;justify-content:flex-end}}@media(max-width:900px){.page-workspace{grid-template-columns:1fr!important}.task-sidebar{position:static!important;height:auto!important;min-height:0!important}.task-list{max-height:320px;overflow:auto}.equal-column{grid-template-columns:1fr!important}}</style>
